CREATE DATABASE IF NOT EXISTS campuscoin_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE campuscoin_db;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('student','admin') NOT NULL DEFAULT 'student',academic_year VARCHAR(30) DEFAULT '',monthly_allowance DECIMAL(12,2) DEFAULT 0,savings_goal DECIMAL(12,2) DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,name VARCHAR(60) NOT NULL,type ENUM('income','expense') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE transactions(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,category_id INT NOT NULL,type ENUM('income','expense') NOT NULL,amount DECIMAL(12,2) NOT NULL,tdate DATE NOT NULL,description VARCHAR(255) DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id,tdate),INDEX(category_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT);
CREATE TABLE budgets(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,category_id INT NOT NULL,month CHAR(7) NOT NULL,amount DECIMAL(12,2) NOT NULL,UNIQUE(user_id,category_id,month),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE);
